return new Promise(function (resolve) {
    setTimeout(function () {
        var name = msg.payload.username;
        // an answer about a name the user has already changed is dropped
        if ((vars.screen.get("formValues") || {}).username !== name) { resolve(null); return; }
        resolve(name === "yeka" || name === "ann" ? [null, { payload: { username: "Already taken" } }] : [{ payload: ["username"] }, null]);
    }, 1800);
});

return new Promise(function (resolve) {
    setTimeout(function () {
        msg.payload = { reset: true };
        resolve(msg);
    }, 1200);
});

props.schema:
return z.object({
    email: z.string().email("Not an email"),
    password: z.string().min(8, "At least 8 characters").regex(/[A-Z]/, "Needs a capital letter").regex(/[0-9]/, "Needs a digit"),
    confirm: z.string(),
    age: z.number({ invalid_type_error: "Age is required" }).int("Whole years only").min(18, "Must be 18 or older")
}).refine(function (v) { return v.password === v.confirm; }, { message: "The passwords are not the same", path: ["confirm"] });

